// Reading the trigger lookup on a trigger node that never fired THROWS in
// this n8n version (confirmed via live E2E testing: running this workflow
// via Manual Trigger alone, with Execute Workflow Trigger never executing,
// crashed here) — wrap in try/catch so both "never executed" and "executed
// with zero items" degrade to the same safe default.
let trigger = {};
try {
  const triggerItems = $('When Executed by Another Workflow').all();
  trigger = triggerItems.length ? triggerItems[0].json : {};
} catch (e) { trigger = {}; }
const asOfDate = trigger.asOfDate || new Date().toISOString().slice(0, 10);
const runType = trigger.runType || 'LIVE';
return [{ json: { asOfDate, runType } }];

const weights = {};
for (const item of $input.all()) {
  weights[item.json.factor] = Number(item.json.weight);
}
return [{ json: { weights } }];

const asOfDate = $('Attach As-Of Date').first().json.asOfDate;
const scannerRunId = $('Get or Create Scanner Run').first().json.id;
const weights = $('Build Weights Map').first().json.weights;
return $input.all().map((item) => ({
  json: { ...item.json, asOfDate, scannerRunId, weights },
}));

/**
 * helpers.js
 *
 * Shared low-level utilities used by every other module in /code and by the
 * equivalent n8n Code nodes. Pure functions only — no I/O, no n8n APIs — so
 * this file can be unit tested with plain `node` and pasted into a Code node
 * body unchanged (just drop the `module.exports` line).
 *
 * Candle shape (normalized, provider-agnostic — see docs/DATA_PROVIDER.md):
 * {
 *   symbol: "COMI",
 *   date: "2026-08-18",     // ISO date, trading session date
 *   open: 100.20,
 *   high: 103.10,
 *   low: 99.80,
 *   close: 102.70,
 *   volume: 12500000,
 *   tradedValue: 1270000000 // optional, derived if absent
 * }
 */

/** Returns true if v is a finite, non-NaN number. */
function isNumber(v) {
  return typeof v === "number" && Number.isFinite(v);
}

/** Safe division: returns null instead of Infinity/NaN when denominator is unusable. */
function safeDivide(numerator, denominator) {
  if (!isNumber(numerator) || !isNumber(denominator) || denominator === 0) {
    return null;
  }
  const result = numerator / denominator;
  return Number.isFinite(result) ? result : null;
}

/** Rounds to `decimals` places, returns null for non-numeric input. */
function round(value, decimals = 4) {
  if (!isNumber(value)) return null;
  const factor = Math.pow(10, decimals);
  return Math.round(value * factor) / factor;
}

/** Percentage change from `from` to `to`. Returns null if from <= 0 or invalid. */
function pctChange(from, to) {
  if (!isNumber(from) || !isNumber(to) || from === 0) return null;
  return ((to - from) / from) * 100;
}

/**
 * Validates a single raw candle. Returns { valid, errors[] }.
 * Mirrors the rules in spec section 31.
 */
function validateCandle(candle) {
  const errors = [];
  if (!candle || typeof candle !== "object") {
    return { valid: false, errors: ["candle is not an object"] };
  }
  const { symbol, date, open, high, low, close, volume } = candle;

  if (!symbol || typeof symbol !== "string") errors.push("missing/invalid symbol");
  if (!date || Number.isNaN(Date.parse(date))) errors.push("missing/invalid date");
  if (!isNumber(open)) errors.push("open is not numeric");
  if (!isNumber(high)) errors.push("high is not numeric");
  if (!isNumber(low)) errors.push("low is not numeric");
  if (!isNumber(close)) errors.push("close is not numeric");
  if (!isNumber(volume)) errors.push("volume is not numeric");

  if (isNumber(open) && isNumber(high) && isNumber(low) && isNumber(close)) {
    if (high < open) errors.push("high < open");
    if (high < close) errors.push("high < close");
    if (high < low) errors.push("high < low");
    if (low > open) errors.push("low > open");
    if (low > close) errors.push("low > close");
  }
  if (isNumber(volume) && volume < 0) errors.push("negative volume");
  if (isNumber(close) && close <= 0) errors.push("close <= 0");

  return { valid: errors.length === 0, errors };
}

/**
 * Filters an array of raw candles into { valid[], invalid[] }.
 * `invalid` entries carry the original candle plus `.errors`.
 * Zero-volume candles are valid but flagged with a warning for downstream
 * consumers (suspicious, not necessarily wrong — EGX thin names do trade zero
 * volume on quiet sessions).
 */
function validateCandles(candles) {
  const valid = [];
  const invalid = [];
  for (const candle of candles || []) {
    const { valid: ok, errors } = validateCandle(candle);
    if (ok) {
      valid.push({ ...candle, suspiciousZeroVolume: candle.volume === 0 });
    } else {
      invalid.push({ ...candle, errors });
    }
  }
  return { valid, invalid };
}

/**
 * Removes duplicate candles (same symbol+date), keeping the last occurrence
 * (assumed most recent fetch / most authoritative).
 */
function dedupeCandles(candles) {
  const map = new Map();
  for (const c of candles || []) {
    map.set(`${c.symbol}::${c.date}`, c);
  }
  return Array.from(map.values());
}

/** Sorts candles ascending by date (oldest first) — mandatory before any TA calc. */
function sortCandlesAscending(candles) {
  return [...(candles || [])].sort((a, b) => new Date(a.date) - new Date(b.date));
}

/**
 * Derives tradedValue when the provider doesn't supply it directly.
 * Uses the session's typical price (H+L+C)/3 * volume as a reasonable proxy.
 */
function deriveTradedValue(candle) {
  if (isNumber(candle.tradedValue)) return candle.tradedValue;
  if (!isNumber(candle.high) || !isNumber(candle.low) || !isNumber(candle.close) || !isNumber(candle.volume)) {
    return null;
  }
  const typicalPrice = (candle.high + candle.low + candle.close) / 3;
  return typicalPrice * candle.volume;
}

/** Simple mean of the last `n` numeric values in `arr` (nulls skipped). Returns null if insufficient data. */
function meanOfLast(arr, n) {
  if (!Array.isArray(arr) || arr.length < n) return null;
  const slice = arr.slice(-n).filter(isNumber);
  if (slice.length < n) return null;
  return slice.reduce((a, b) => a + b, 0) / n;
}

/** Standard deviation of the last `n` numeric values. Returns null if insufficient data. */
function stdDevOfLast(arr, n) {
  const mean = meanOfLast(arr, n);
  if (mean === null) return null;
  const slice = arr.slice(-n);
  const variance = slice.reduce((sum, v) => sum + Math.pow(v - mean, 2), 0) / n;
  return Math.sqrt(variance);
}

/** Clamps a number into [min, max]. */
function clamp(value, min, max) {
  if (!isNumber(value)) return min;
  return Math.min(Math.max(value, min), max);
}

/**
 * Wraps arbitrary rows into n8n's expected item structure: [{ json: {...} }].
 * Accepts a single object or array of objects.
 */
function toN8nItems(rows) {
  const list = Array.isArray(rows) ? rows : [rows];
  return list.map((json) => ({ json }));
}

/**
 * Reads all `json` payloads out of an n8n items array back into plain objects.
 */
function fromN8nItems(items) {
  return (items || []).map((item) => item.json);
}

// ---------------------------------------------------------------------

/**
 * overallScore.js
 *
 * Composes the final 0-100 overall_score from the independent sub-scores
 * using CONFIGURABLE weights (spec section 21 — never a flat average across
 * setup types, since a strong breakout and a strong pullback aren't
 * comparable on the same raw scale). Also performs setup classification
 * (section 22) and setup/data confidence (section 44).
 *
 * Weights are read from the `scoring_weights` table (profile 'default'
 * unless overridden) by the ranking workflow's Postgres node and passed in
 * as `weights` here — this module has no DB access of its own.
 */


const DEFAULT_WEIGHTS = {
  trend: 20,
  volume: 20,
  momentum: 15,
  breakout: 15,
  price_structure: 10,
  macd: 5,
  rsi: 5,
  relative_strength: 5,
  risk_reward: 5,
};

/**
 * `factors` — normalized 0-100 sub-scores for each weighted dimension:
 * { trend, volume, momentum, breakout, priceStructure, macd, rsi, relativeStrength, riskReward }
 * `subScores` — the four setup scanner outputs: { breakoutScore, momentumScore, pullbackScore, reversalScore, accumulationScore }
 * `weights` — optional override of DEFAULT_WEIGHTS (same keys, snake_case, from scoring_weights table)
 */
function calculateOverallScore(factors, weights = DEFAULT_WEIGHTS) {
  const w = { ...DEFAULT_WEIGHTS, ...weights };
  const weightSum = Object.values(w).reduce((a, b) => a + (isNumber(b) ? b : 0), 0) || 100;

  const contributions = {
    trend: safeFactor(factors.trend) * (w.trend / weightSum),
    volume: safeFactor(factors.volume) * (w.volume / weightSum),
    momentum: safeFactor(factors.momentum) * (w.momentum / weightSum),
    breakout: safeFactor(factors.breakout) * (w.breakout / weightSum),
    priceStructure: safeFactor(factors.priceStructure) * (w.price_structure / weightSum),
    macd: safeFactor(factors.macd) * (w.macd / weightSum),
    rsi: safeFactor(factors.rsi) * (w.rsi / weightSum),
    relativeStrength: safeFactor(factors.relativeStrength) * (w.relative_strength / weightSum),
    riskReward: safeFactor(factors.riskReward) * (w.risk_reward / weightSum),
  };

  const overallScore = clamp(
    round(Object.values(contributions).reduce((a, b) => a + b, 0), 2),
    0,
    100
  );

  return { overallScore, contributions };
}

function safeFactor(v) {
  return isNumber(v) ? clamp(v, 0, 100) : 0;
}

/**
 * Setup classification (spec section 22). Picks the single dominant
 * sub-score above a minimum bar; if nothing clears the bar, classifies
 * NEUTRAL, or AVOID when the stock is fundamentally disqualified
 * (illiquid / insufficient data), which callers pass explicitly.
 */
function classifySetupType(subScores, { eligible = true, minScore = 55 } = {}) {
  if (!eligible) return "AVOID";

  const candidates = [
    { type: "BREAKOUT", score: subScores.breakoutScore },
    { type: "MOMENTUM", score: subScores.momentumScore },
    { type: "PULLBACK", score: subScores.pullbackScore },
    { type: "REVERSAL", score: subScores.reversalScore },
    { type: "ACCUMULATION", score: subScores.accumulationScore },
  ].filter((c) => isNumber(c.score));

  if (!candidates.length) return "NEUTRAL";

  candidates.sort((a, b) => b.score - a.score);
  const top = candidates[0];

  return top.score >= minScore ? top.type : "NEUTRAL";
}

/**
 * Setup confidence (section 44): how much we trust the classification itself
 * — driven by the margin between the winning sub-score and the runner-up
 * (a clean win is more trustworthy than a narrow one) and the winning
 * sub-score's absolute strength.
 */
function calculateSetupConfidence(subScores) {
  const scores = [
    subScores.breakoutScore,
    subScores.momentumScore,
    subScores.pullbackScore,
    subScores.reversalScore,
    subScores.accumulationScore,
  ].filter(isNumber).sort((a, b) => b - a);

  if (!scores.length) return 0;
  const top = scores[0];
  const runnerUp = scores[1] ?? 0;
  const margin = top - runnerUp;

  const confidence = clamp(top * 0.6 + Math.min(margin, 40) * 1.0, 0, 100);
  return round(confidence, 2);
}

// ---------------------------------------------------------------------

/**
 * riskReward.js
 *
 * Derives entry/invalidation/target trade structure from real support/
 * resistance/ATR/close inputs (spec section 20). Never invents arbitrary
 * "guaranteed" targets — targets are always resistance levels, support
 * levels, or ATR multiples actually present in the data. Rejects any
 * risk/reward calculation where risk <= 0.
 */


/**
 * `close`, `atr14` — latest bar values.
 * `resistances` — [resistance1, resistance2, resistance3] (nulls allowed).
 * `supports` — [support1, support2, support3] (nulls allowed).
 * `setupType` — one of BREAKOUT | MOMENTUM | PULLBACK | REVERSAL | ACCUMULATION.
 *
 * Returns { entry, invalidation, target1, target2, target3, riskRewardT1/2/3 }.
 * Any field that cannot be derived from real structure is left null rather
 * than guessed.
 */
function buildTradeStructure({ close, atr14, resistances = [], supports = [], setupType }) {
  if (!isNumber(close)) {
    return emptyStructure();
  }

  const [r1, r2, r3] = resistances;
  const [s1, s2, s3] = supports;
  const atr = isNumber(atr14) ? atr14 : null;

  let entry = null;
  let invalidation = null;

  switch (setupType) {
    case "BREAKOUT":
      // Entry triggers on a confirmed break above resistance1 (small buffer);
      // invalidation sits just below the breakout level / recent support.
      entry = isNumber(r1) ? r1 * 1.002 : close;
      invalidation = isNumber(s1) ? s1 : (atr ? close - atr * 1.5 : null);
      break;

    case "MOMENTUM":
      entry = close;
      invalidation = atr ? close - atr * 1.5 : (isNumber(s1) ? s1 : null);
      break;

    case "PULLBACK":
      entry = isNumber(s1) ? Math.max(s1, close) : close;
      invalidation = isNumber(s1) ? s1 * 0.985 : (atr ? close - atr * 1.2 : null);
      break;

    case "REVERSAL":
      entry = close;
      invalidation = isNumber(s1) ? s1 * 0.985 : (atr ? close - atr * 1.2 : null);
      break;

    default:
      entry = close;
      invalidation = atr ? close - atr * 1.5 : null;
  }

  const targets = deriveTargets({ entry: entry ?? close, close, atr, resistances: [r1, r2, r3] });
  const risk = isNumber(entry) && isNumber(invalidation) ? entry - invalidation : null;

  const withRR = targets.map((t) => ({
    target: t,
    riskReward: computeRiskReward(entry, invalidation, t),
    gainPct: calculateGainPct(entry, t),
    estimatedDays: estimateDaysToTarget(entry, t, atr),
  }));

  return {
    entry: round(entry, 6),
    invalidation: round(invalidation, 6),
    target1: round(withRR[0]?.target ?? null, 6),
    target2: round(withRR[1]?.target ?? null, 6),
    target3: round(withRR[2]?.target ?? null, 6),
    riskRewardT1: round(withRR[0]?.riskReward ?? null, 4),
    riskRewardT2: round(withRR[1]?.riskReward ?? null, 4),
    riskRewardT3: round(withRR[2]?.riskReward ?? null, 4),
    riskAmount: isNumber(risk) && risk > 0 ? round(risk, 6) : null,
    target1GainPct: round(withRR[0]?.gainPct ?? null, 4),
    target2GainPct: round(withRR[1]?.gainPct ?? null, 4),
    target3GainPct: round(withRR[2]?.gainPct ?? null, 4),
    target1EstimatedDays: withRR[0]?.estimatedDays ?? null,
    target2EstimatedDays: withRR[1]?.estimatedDays ?? null,
    target3EstimatedDays: withRR[2]?.estimatedDays ?? null,
  };
}

/**
 * Potential gain (%) from entry to a target, IF that target is reached.
 * This is arithmetic on real entry/target prices, not a forecast — it says
 * nothing about whether or when the target will actually be hit.
 */
function calculateGainPct(entry, target) {
  if (!isNumber(entry) || !isNumber(target) || entry <= 0) return null;
  return ((target - entry) / entry) * 100;
}

/**
 * Rough projection of trading sessions to cover the distance to a target,
 * using the stock's own ATR14 (average daily true range) as the only speed
 * reference available. Deliberately conservative: assumes the stock closes
 * roughly HALF its average daily range in net progress toward the target
 * each session (ATR measures full high-low range, not net directional
 * movement, and price rarely trends in a straight line) — a 0.5x factor,
 * not tuned or backtested. This is a same-order-of-magnitude estimate for
 * "how far is this, in this stock's own volatility terms", not a forecast
 * of when the target will be hit, and not derived from any historical
 * track record. Returns null when there isn't enough data to estimate from.
 */
function estimateDaysToTarget(entry, target, atr14) {
  if (!isNumber(entry) || !isNumber(target) || !isNumber(atr14) || atr14 <= 0) return null;
  const distance = target - entry;
  if (distance <= 0) return null;
  const assumedDailyProgress = atr14 * 0.5;
  return Math.max(1, Math.ceil(distance / assumedDailyProgress));
}

/**
 * Targets prefer real resistance levels above entry; when a resistance slot
 * is missing/already passed, falls back to an ATR multiple projection
 * (1.5x / 2.5x / 3.5x ATR from entry) so a target is still an evidence-based
 * projection, never a fixed arbitrary percentage.
 */
function deriveTargets({ entry, close, atr, resistances }) {
  const candidates = resistances.filter((r) => isNumber(r) && r > entry);
  const targets = [];

  for (let i = 0; i < 3; i++) {
    if (candidates[i] !== undefined) {
      targets.push(candidates[i]);
    } else if (isNumber(atr)) {
      const multiple = [1.5, 2.5, 3.5][i];
      targets.push(entry + atr * multiple);
    } else {
      targets.push(null);
    }
  }
  return targets;
}

function computeRiskReward(entry, invalidation, target) {
  if (!isNumber(entry) || !isNumber(invalidation) || !isNumber(target)) return null;
  const risk = entry - invalidation;
  const reward = target - entry;
  if (risk <= 0) return null; // invalid: invalidation must be below entry
  return safeDivide(reward, risk);
}

function emptyStructure() {
  return {
    entry: null,
    invalidation: null,
    target1: null,
    target2: null,
    target3: null,
    riskRewardT1: null,
    riskRewardT2: null,
    riskRewardT3: null,
    riskAmount: null,
    target1GainPct: null,
    target2GainPct: null,
    target3GainPct: null,
    target1EstimatedDays: null,
    target2EstimatedDays: null,
    target3EstimatedDays: null,
  };
}

// Runs once for the WHOLE batch — one item per active stock arrives here
// from "Load Ranking Inputs". Must loop $input.all() explicitly (confirmed
// as a real bug via live E2E testing against 20 real EGX stocks:
// $input.first() silently only ranked the first stock). itemMatching(i)
// pairs each row back to its stock.

const minAvgTradedValue = Number($env.MIN_AVG_TRADED_VALUE) || 0;
const minAvgVolume = Number($env.MIN_AVG_VOLUME) || 0;
const minActiveDays20 = Number($env.MIN_ACTIVE_DAYS_20) || 15;

function scoreOneStock(row, weights) {
  if (!isNumber(row.close)) {
    return {
      eligible: false, eligibilityReason: 'No price data for scan date',
      overallScore: 0, setupType: 'AVOID', dataConfidence: 0, setupConfidence: 0,
      entry: null, invalidation: null, target1: null, target2: null, target3: null,
      riskRewardT1: null, riskRewardT2: null, riskRewardT3: null, accumulationScore: 0,
      target1GainPct: null, target2GainPct: null, target3GainPct: null,
      target1EstimatedDays: null, target2EstimatedDays: null, target3EstimatedDays: null,
    };
  }

  const reasons = [];
  let eligible = true;
  if (!isNumber(row.avg_traded_value20) || row.avg_traded_value20 < minAvgTradedValue) {
    eligible = false; reasons.push('avg traded value below MIN_AVG_TRADED_VALUE');
  }
  if (!isNumber(row.avg_volume20) || row.avg_volume20 < minAvgVolume) {
    eligible = false; reasons.push('avg volume below MIN_AVG_VOLUME');
  }
  if (!isNumber(row.active_days20) || row.active_days20 < minActiveDays20) {
    eligible = false; reasons.push('fewer than MIN_ACTIVE_DAYS_20 traded sessions in the last 20');
  }
  const eligibilityReason = eligible ? null : reasons.join('; ');

  const trendMap = { STRONG_BULLISH: 100, BULLISH: 75, NEUTRAL: 50, BEARISH: 25, STRONG_BEARISH: 0 };
  const trendFactor = trendMap[row.medium_term_trend] ?? 50;

  const volumeFactor = isNumber(row.relative_volume20) ? clamp((row.relative_volume20 / 3) * 100, 0, 100) : 0;

  const macdFactor = isNumber(row.macd_histogram)
    ? clamp(50 + row.macd_histogram * 200, 0, 100)
    : 50;

  // RSI isn't directly in this query (already spent on the scanners); use
  // momentum_score as a stand-in signal for "is momentum/RSI supportive" —
  // documented approximation, see docs/SCORING.md.
  const rsiFactor = isNumber(row.momentum_score) ? row.momentum_score : 50;

  const priceStructureFactor = isNumber(row.nearest_resistance_distance_pct)
    ? clamp(100 - Math.min(100, row.nearest_resistance_distance_pct * 10), 0, 100)
    : 50;

  const return20d = isNumber(row.close20d_ago) && row.close20d_ago > 0
    ? ((row.close - row.close20d_ago) / row.close20d_ago) * 100
    : null;
  const relativeStrengthFactor = isNumber(return20d) ? clamp(50 + return20d * 3, 0, 100) : 50;

  const subScores = {
    breakoutScore: row.breakout_score || 0,
    momentumScore: row.momentum_score || 0,
    pullbackScore: row.pullback_score || 0,
    reversalScore: row.reversal_score || 0,
    accumulationScore: row.accumulation_score || 0,
  };

  const setupType = classifySetupType(subScores, { eligible });
  const setupConfidence = calculateSetupConfidence(subScores);

  // Provisional risk/reward factor needs a trade structure — build it first
  // with a rough entry (close), then feed the resulting riskRewardT1 back in.
  const tradeStructure = buildTradeStructure({
    close: row.close, atr14: row.atr14,
    resistances: [row.resistance1, row.resistance2, row.resistance3],
    supports: [row.support1, row.support2, row.support3],
    setupType,
  });
  const riskRewardFactor = isNumber(tradeStructure.riskRewardT1)
    ? clamp(tradeStructure.riskRewardT1 * 30, 0, 100)
    : 0;

  const { overallScore } = calculateOverallScore({
    trend: trendFactor,
    volume: volumeFactor,
    momentum: subScores.momentumScore,
    breakout: subScores.breakoutScore,
    priceStructure: priceStructureFactor,
    macd: macdFactor,
    rsi: rsiFactor,
    relativeStrength: relativeStrengthFactor,
    riskReward: riskRewardFactor,
  }, weights);

  return {
    eligible, eligibilityReason,
    overallScore,
    setupType,
    dataConfidence: row.data_confidence,
    setupConfidence,
    accumulationScore: subScores.accumulationScore,
    entry: tradeStructure.entry,
    invalidation: tradeStructure.invalidation,
    target1: tradeStructure.target1,
    target2: tradeStructure.target2,
    target3: tradeStructure.target3,
    riskRewardT1: tradeStructure.riskRewardT1,
    riskRewardT2: tradeStructure.riskRewardT2,
    riskRewardT3: tradeStructure.riskRewardT3,
    target1GainPct: tradeStructure.target1GainPct,
    target2GainPct: tradeStructure.target2GainPct,
    target3GainPct: tradeStructure.target3GainPct,
    target1EstimatedDays: tradeStructure.target1EstimatedDays,
    target2EstimatedDays: tradeStructure.target2EstimatedDays,
    target3EstimatedDays: tradeStructure.target3EstimatedDays,
  };
}

const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  let original;
  try { original = $('Attach Ranking Context').itemMatching(i).json; } catch (e) { continue; }
  const stockId = original.id;
  const scannerRunId = original.scannerRunId;
  const weights = original.weights;

  const row = items[i].json;
  const scored = scoreOneStock(row, weights);

  out.push({ json: { stockId, scannerRunId, ...scored } });
}

return out;

parameters.query:
UPDATE scanner_results sr SET overall_rank = ranked.rnk
FROM (
  SELECT id, RANK() OVER (ORDER BY overall_score DESC) AS rnk
  FROM scanner_results WHERE scanner_run_id = $1
) ranked
WHERE sr.id = ranked.id;

